import sys
def db_prefix(k, n, length):
    # FKM algorithm generator for de Bruijn sequence B(k,n)
    a = [0] * (k * n)
    out = []
    def gen():
        # iterative version of db(t, p)
        stack = [(1, 1, 0)]
        # use recursion via explicit generator (python recursion depth fine for n=3)
        def db(t, p):
            if t > n:
                if n % p == 0:
                    for v in a[1:p+1]:
