            else:
                a[t] = a[t - p]
                yield from db(t + 1, p)
                for j in range(a[t - p] + 1, k):
                    a[t] = j
                    yield from db(t + 1, t)
        yield from db(1, 1)
    for v in gen():
        out.append(v)
        if len(out) >= length: break
    return bytes(out)
