//! DEFLATE encoder model (work in progress).

pub struct BitWriter {
    pub out: Vec<u8>,
    acc: u64,
    n: u32,
}

impl BitWriter {
    pub fn new() -> Self {
        BitWriter { out: Vec::new(), acc: 0, n: 0 }
    }
    /// Write `n` bits of `value`, LSB first. NOTE: `value` is deliberately NOT
    /// masked to `n` bits (the original leaks the high bits into later fields).
    #[inline]
    pub fn put(&mut self, value: u32, n: u32) {
        self.acc |= (value as u64) << self.n;
        self.n += n;
        while self.n >= 8 {
            self.out.push(self.acc as u8);
            self.acc >>= 8;
            self.n -= 8;
        }
    }
    /// Write a Huffman code (MSB-first code bits).
    #[inline]
    pub fn put_code(&mut self, code: u32, len: u32) {
        let mut r = 0u32;
        for i in 0..len {
            if code & (1 << i) != 0 {
                r |= 1 << (len - 1 - i);
            }
        }
        self.put(r, len);
    }
    pub fn finish(mut self) -> Vec<u8> {
        if self.n > 0 {
            self.out.push(self.acc as u8);
        }
        self.out
    }
}

