# Bit writer for crafting deflate/brotli streams (LSB-first).
class BW:
    def __init__(self):
        self.bits = []
    def put(self, v, n):
        for i in range(n):
            self.bits.append((v >> i) & 1)
    def code(self, c, n):  # huffman code MSB-first
        for i in range(n - 1, -1, -1):
            self.bits.append((c >> i) & 1)
    def align(self):
        while len(self.bits) % 8:
            self.bits.append(0)
    def bytes(self):
        b = list(self.bits)
        while len(b) % 8:
            b.append(0)
        out = bytearray()
        for i in range(0, len(b), 8):
            v = 0
            for j in range(8):
                v |= b[i + j] << j
            out.append(v)
        return bytes(out)
    def raw(self, bs):
        self.align()
        for x in bs:
            self.put(x, 8)

def canon_codes(lengths):
    maxl = max(lengths) if lengths else 0
    bl = [0] * (max(maxl, 15) + 2)
    for l in lengths:
        if l: bl[l] += 1
    code = 0
    nxt = [0] * (len(bl) + 1)
    for b in range(1, len(bl)):
        code = (code + bl[b - 1]) << 1
        nxt[b] = code
    codes = [0] * len(lengths)
    for i, l in enumerate(lengths):
        if l:
            codes[i] = nxt[l]
            nxt[l] += 1
    return codes

CL_ORDER = [16, 17, 18, 0, 8, 7, 9, 6, 10, 5, 11, 4, 12, 3, 13, 2, 14, 1, 15]

def fixed_lit(bw, sym):
    if sym < 144: bw.code(0x30 + sym, 8)
    elif sym < 256: bw.code(0x190 + sym - 144, 9)
    elif sym < 280: bw.code(sym - 256, 7)
    else: bw.code(0xC0 + sym - 280, 8)

def dyn_header(bw, litlens, distlens, cl_lens=None, hclen=None, cl_syms=None):
    """Write dynamic header. litlens (257..288 entries), distlens (1..32).
    cl_syms: optional explicit list of (sym, extra_bits_value) for the code-length sequence."""
    hlit = len(litlens); hdist = len(distlens)
    if cl_syms is None:
        cl_syms = [(l, None) for l in litlens + distlens]
    if cl_lens is None:
        # build code length code: all used symbols get length from simple scheme
        used = sorted(set(s for s, _ in cl_syms))
        cl_lens = [0] * 19
        # assign lengths making a complete code if possible
        import math
        n = len(used)
        if n == 1:
            cl_lens[used[0]] = 1
        else:
            # use a balanced code: lengths k or k+1
            k = max(1, math.ceil(math.log2(n)))
            # number of k-length codes such that kraft sum = 1
            # a*2^-k + b*2^-(k+1)... simple: all length k (may be incomplete)
            for s in used: cl_lens[s] = k
    if hclen is None:
        hclen = 19
        while hclen > 4 and cl_lens[CL_ORDER[hclen - 1]] == 0:
            hclen -= 1
    bw.put(hlit - 257, 5); bw.put(hdist - 1, 5); bw.put(hclen - 4, 4)
    for i in range(hclen):
        bw.put(cl_lens[CL_ORDER[i]], 3)
    clc = canon_codes(cl_lens)
    for s, extra in cl_syms:
        bw.code(clc[s], cl_lens[s])
        if s == 16: bw.put(extra, 2)
        elif s == 17: bw.put(extra, 3)
        elif s == 18: bw.put(extra, 7)
    return canon_codes(litlens), canon_codes(distlens)
