pub struct Br<'a> {
    data: &'a [u8],
    pos: usize,
    bit: u32, // bit offset within data[pos]
}

impl<'a> Br<'a> {
    fn new(data: &'a [u8]) -> Self {
        Br { data, pos: 0, bit: 0 }
    }
    #[inline]
    fn bits_left(&self) -> usize {
        (self.data.len() - self.pos) * 8 - self.bit as usize
    }
    #[inline]
    fn read(&mut self, n: u32) -> Result<u32, CodecError> {
        if n == 0 {
            return Ok(0);
        }
        if (self.bits_left() as u64) < n as u64 {
            return Err(err("unexpected end of input"));
        }
        let mut v: u64 = 0;
        let mut got = 0u32;
        while got < n {
            let avail = 8 - self.bit;
            let take = avail.min(n - got);
            let b = (self.data[self.pos] >> self.bit) as u64 & ((1u64 << take) - 1);
            v |= b << got;
            got += take;
            self.bit += take;
            if self.bit == 8 {
                self.bit = 0;
                self.pos += 1;
            }
        }
        Ok(v as u32)
    }
    /// Peek up to 16 bits; returns (value, available bit count).
    #[inline]
    fn peek16(&self) -> (u32, u32) {
        let mut v: u32 = 0;
        let mut got = 0u32;
        let mut p = self.pos;
        let mut bit = self.bit;
        while got < 16 && p < self.data.len() {
            let avail = 8 - bit;
            let b = (self.data[p] >> bit) as u32;
            v |= b << got;
            got += avail;
            p += 1;
            bit = 0;
        }
        let got = got.min(16);
        (v & ((1u32 << got) - 1).max(if got == 32 { u32::MAX } else { 0 }), got)
    }
    #[inline]
    fn skip(&mut self, n: u32) {
        let t = self.bit + n;
        self.pos += (t / 8) as usize;
        self.bit = t % 8;
    }
    /// Remaining bits up to the byte boundary; returns their value.
    fn align(&mut self) -> u32 {
        if self.bit == 0 {
            return 0;
        }
        let v = (self.data[self.pos] >> self.bit) as u32;
        self.bit = 0;
        self.pos += 1;
        v
    }
}

/// Canonical prefix code with a 2-level-free simple table: we decode with a
/// full 15-bit lookup table only when small; otherwise bit-by-bit.
pub struct Huff {
    // table indexed by up to `bits` reversed code bits: (symbol << 4) | len
    table: Vec<u32>,
    bits: u32,
    single: Option<u16>,
}

impl Huff {
    fn from_lengths(lengths: &[u8]) -> Huff {
        let nz: Vec<usize> = (0..lengths.len()).filter(|&i| lengths[i] != 0).collect();
        if nz.len() == 1 && lengths[nz[0]] == 0 {
            unreachable!()
        }
        let max = lengths.iter().copied().max().unwrap_or(0) as u32;
        let bits = max.max(1);
        let mut table = vec![0u32; 1 << bits];
        let mut bl_count = [0u32; 16];
        for &l in lengths {
            if l != 0 {
                bl_count[l as usize] += 1;
            }
        }
        let mut next = [0u32; 16];
        let mut code = 0u32;
        for b in 1..16 {
            code = (code + bl_count[b - 1]) << 1;
            next[b] = code;
        }
        for (s, &l) in lengths.iter().enumerate() {
            if l == 0 {
                continue;
            }
            let l = l as u32;
            let c = next[l as usize];
            next[l as usize] += 1;
            let mut r = 0u32;
            for i in 0..l {
                if c & (1 << i) != 0 {
                    r |= 1 << (l - 1 - i);
                }
            }
            let mut i = r;
            while i < (1 << bits) {
                table[i as usize] = ((s as u32) << 4) | l;
                i += 1 << l;
            }
        }
        Huff { table, bits, single: None }
    }
    fn single(sym: u16) -> Huff {
        Huff { table: Vec::new(), bits: 0, single: Some(sym) }
    }
    #[inline]
    fn decode(&self, br: &mut Br) -> Result<u32, CodecError> {
        if let Some(s) = self.single {
            return Ok(s as u32);
        }
        let (v, avail) = br.peek16();
        let e = self.table[(v & ((1 << self.bits) - 1)) as usize];
        let l = e & 15;
        if l == 0 {
            return Err(err("invalid prefix code"));
        }
        if l > avail {
            return Err(err("unexpected end of input"));
        }
        br.skip(l);
        Ok(e >> 4)
    }
}

fn read_varlen8(br: &mut Br) -> Result<u32, CodecError> {
    if br.read(1)? == 0 {
        return Ok(0);
    }
    let n = br.read(3)?;
    if n == 0 {
        return Ok(1);
    }
    Ok(br.read(n)? + (1 << n))
}

fn read_prefix_code(br: &mut Br, alphabet: usize) -> Result<Huff, CodecError> {
    let hskip = br.read(2)?;
    let alpha_bits = 32 - ((alphabet as u32) - 1).leading_zeros();
    let alpha_bits = alpha_bits.max(1);
    if hskip == 1 {
        let nsym = br.read(2)? as usize + 1;
        let mut syms = [0u16; 4];
        for s in syms.iter_mut().take(nsym) {
            let v = br.read(alpha_bits)?;
            if v as usize >= alphabet {
                return Err(err("invalid simple prefix code symbol"));
            }
            *s = v as u16;
        }
        for i in 0..nsym {
            for j in i + 1..nsym {
                if syms[i] == syms[j] {
                    return Err(err("duplicate symbol in simple prefix code"));
                }
            }
        }
        let mut lengths = vec![0u8; alphabet];
        match nsym {
            1 => return Ok(Huff::single(syms[0])),
            2 => {
                lengths[syms[0] as usize] = 1;
                lengths[syms[1] as usize] = 1;
            }
            3 => {
                lengths[syms[0] as usize] = 1;
                lengths[syms[1] as usize] = 2;
                lengths[syms[2] as usize] = 2;
            }
            _ => {
                let tree_select = br.read(1)?;
                if tree_select == 0 {
                    for s in syms.iter() {
                        lengths[*s as usize] = 2;
                    }
                } else {
                    lengths[syms[0] as usize] = 1;
                    lengths[syms[1] as usize] = 2;
                    lengths[syms[2] as usize] = 3;
                    lengths[syms[3] as usize] = 3;
                }
            }
        }
        return Ok(Huff::from_lengths(&lengths));
    }
    // complex prefix code
    let mut cl_lens = [0u8; 18];
    let mut space: i32 = 32;
    let mut num_codes = 0;
    for &idx in CL_ORDER.iter().skip(hskip as usize) {
        // fixed variable-length code for code length code lengths
        let (v, avail) = br.peek16();
        let v4 = v & 15;
        const PLEN: [u32; 16] = [2, 2, 2, 3, 2, 2, 2, 4, 2, 2, 2, 3, 2, 2, 2, 4];
        const PVAL: [u8; 16] = [0, 4, 3, 2, 0, 4, 3, 1, 0, 4, 3, 2, 0, 4, 3, 5];
        let l = PLEN[v4 as usize];
        if l > avail {
            return Err(err("unexpected end of input"));
        }
        br.skip(l);
        let val = PVAL[v4 as usize];
        cl_lens[idx] = val;
        if val != 0 {
            space -= 32 >> val;
            num_codes += 1;
            if space <= 0 {
                break;
            }
        }
    }
    if !(num_codes == 1 || space == 0) {
        return Err(err("invalid code length code"));
    }
    let clh = if num_codes == 1 {
        let s = (0..18).find(|&i| cl_lens[i] != 0).unwrap();
        Huff::single(s as u16)
    } else {
        Huff::from_lengths(&cl_lens)
    };
    let mut lengths = vec![0u8; alphabet];
    let mut symbol = 0usize;
    let mut prev_len: u8 = 8;
    let mut repeat: u32 = 0;
    let mut repeat_len: u8 = 0;
    let mut space: i32 = 32768;
    while symbol < alphabet && space > 0 {
        let c = clh.decode(br)? as u8;
        if c < 16 {
            repeat = 0;
            lengths[symbol] = c;
            if c != 0 {
                prev_len = c;
                space -= 32768 >> c;
            }
            symbol += 1;
        } else {
            let extra_bits = if c == 16 { 2 } else { 3 };
            let new_len = if c == 16 { prev_len } else { 0 };
            if repeat_len != new_len {
                repeat = 0;
                repeat_len = new_len;
            }
            let old = repeat;
            if repeat > 0 {
                repeat -= 2;
                repeat <<= extra_bits;
            }
            repeat += br.read(extra_bits)? + 3;
            let delta = (repeat - old) as usize;
            if symbol + delta > alphabet {
                return Err(err("invalid repeat"));
            }
            for l in lengths.iter_mut().skip(symbol).take(delta) {
                *l = repeat_len;
            }
            symbol += delta;
            if repeat_len != 0 {
                space -= (delta as i32) << (15 - repeat_len);
            }
        }
    }
    if space != 0 {
        return Err(err("invalid prefix code space"));
    }
    let nz = lengths.iter().filter(|&&l| l != 0).count();
    if nz == 1 {
        let s = lengths.iter().position(|&l| l != 0).unwrap();
        return Ok(Huff::single(s as u16));
    }
    Ok(Huff::from_lengths(&lengths))
}

fn read_block_len(br: &mut Br, h: &Huff) -> Result<u32, CodecError> {
    let c = h.decode(br)? as usize;
    Ok(BLEN_BASE[c] + br.read(BLEN_EXTRA[c])?)
}

fn read_context_map(br: &mut Br, size: usize, ntrees: usize) -> Result<Vec<u8>, CodecError> {
    let mut map = vec![0u8; size];
    if ntrees < 2 {
        return Ok(map);
    }
    let rlemax = if br.read(1)? == 1 { br.read(4)? + 1 } else { 0 };
    let h = read_prefix_code(br, ntrees + rlemax as usize)?;
    let mut i = 0;
    while i < size {
        let code = h.decode(br)?;
        if code == 0 {
            map[i] = 0;
            i += 1;
        } else if code > rlemax {
            map[i] = (code - rlemax) as u8;
            i += 1;
        } else {
            let reps = (1usize << code) + br.read(code)? as usize;
            if i + reps > size {
                return Err(err("invalid context map"));
            }
            i += reps;
        }
    }
    if br.read(1)? == 1 {
        // inverse move-to-front
        let mut mtf: Vec<u8> = (0..=255u8).collect();
        for v in map.iter_mut() {
            let idx = *v as usize;
            let val = mtf[idx];
            *v = val;
            mtf.remove(idx);
            mtf.insert(0, val);
        }
    }
    Ok(map)
}

struct BlockState {
    ntypes: u32,
    types_h: Option<Huff>,
    len_h: Option<Huff>,
    btype: u32,
    rb: [u32; 2],
    left: u32,
}

impl BlockState {
    fn read(br: &mut Br) -> Result<BlockState, CodecError> {
        let ntypes = read_varlen8(br)? + 1;
        if ntypes >= 2 {
            let th = read_prefix_code(br, ntypes as usize + 2)?;
            let lh = read_prefix_code(br, 26)?;
            let left = read_block_len(br, &lh)?;
            Ok(BlockState { ntypes, types_h: Some(th), len_h: Some(lh), btype: 0, rb: [1, 0], left })
        } else {
            Ok(BlockState { ntypes, types_h: None, len_h: None, btype: 0, rb: [1, 0], left: 1 << 28 })
        }
    }
    fn switch(&mut self, br: &mut Br) -> Result<(), CodecError> {
        let th = match &self.types_h {
            Some(h) => h,
            None => {
                self.left = 1 << 28;
                return Ok(());
            }
        };
        let mut t = th.decode(br)?;
        let len = read_block_len(br, self.len_h.as_ref().unwrap())?;
        t = match t {
            0 => self.rb[0],
            1 => self.rb[1] + 1,
            n => n - 2,
        };
        if t >= self.ntypes {
            t -= self.ntypes;
        }
        self.rb[0] = self.rb[1];
        self.rb[1] = t;
        self.btype = t;
        self.left = len;
        Ok(())
    }
}

pub fn decode(data: &[u8]) -> Result<Vec<u8>, CodecError> {
    let mut br = Br::new(data);
    // window bits
    let wbits: u32 = if br.read(1)? == 0 {
        16
    } else {
        let n = br.read(3)?;
        if n != 0 {
            17 + n
        } else {
            let m = br.read(3)?;
            if m == 1 {
                return Err(err("large-window streams are not supported"));
            }
            if m != 0 {
                8 + m
            } else {
                17
            }
        }
    };
    let max_backward: usize = (1usize << wbits) - 16;
    let mut out: Vec<u8> = Vec::new();
    let mut dist_rb: [i64; 4] = [16, 15, 11, 4];
    let mut dist_rb_idx: usize = 0;
    loop {
        let islast = br.read(1)? == 1;
        if islast && br.read(1)? == 1 {
            break;
        }
        let mn = br.read(2)?;
        if mn == 3 {
            // metadata
            if br.read(1)? != 0 {
                return Err(err("reserved bit set"));
            }
            let skipbytes = br.read(2)?;
            let mut skiplen: usize = 0;
            for i in 0..skipbytes {
                let b = br.read(8)? as usize;
                if i + 1 == skipbytes && skipbytes > 1 && b == 0 {
                    return Err(err("exuberant metadata nibble"));
                }
                skiplen |= b << (8 * i);
            }
            if skipbytes > 0 {
                skiplen += 1;
            }
            br.align();
            if br.pos + skiplen > data.len() {
                return Err(err("unexpected end of input"));
            }
            br.pos += skiplen;
            if islast {
                break;
            }
            continue;
        }
        let nibbles = mn + 4;
        let mut mlen: usize = 0;
        for i in 0..nibbles {
            let v = br.read(4)? as usize;
            if i + 1 == nibbles && nibbles > 4 && v == 0 {
                return Err(err("exuberant nibble"));
            }
            mlen |= v << (4 * i);
        }
        mlen += 1;
        let uncompressed = if !islast { br.read(1)? == 1 } else { false };
        if uncompressed {
            br.align();
            if br.pos + mlen > data.len() {
                return Err(err("uncompressed block overruns input"));
            }
            out.extend_from_slice(&data[br.pos..br.pos + mlen]);
            br.pos += mlen;
            continue;
        }
        // compressed meta-block
        let mut bl = BlockState::read(&mut br)?;
        let mut bi = BlockState::read(&mut br)?;
        let mut bd = BlockState::read(&mut br)?;
        let npostfix = br.read(2)?;
        let ndirect = br.read(4)? << npostfix;
        let mut cmodes = Vec::with_capacity(bl.ntypes as usize);
        for _ in 0..bl.ntypes {
            cmodes.push(br.read(2)? as u8);
        }
        let ntreesl = read_varlen8(&mut br)? as usize + 1;
        let cmap_l = read_context_map(&mut br, 64 * bl.ntypes as usize, ntreesl)?;
        let ntreesd = read_varlen8(&mut br)? as usize + 1;
        let cmap_d = read_context_map(&mut br, 4 * bd.ntypes as usize, ntreesd)?;
        let mut lit_h = Vec::with_capacity(ntreesl);
        for _ in 0..ntreesl {
            lit_h.push(read_prefix_code(&mut br, 256)?);
        }
        let mut cmd_h = Vec::with_capacity(bi.ntypes as usize);
        for _ in 0..bi.ntypes {
            cmd_h.push(read_prefix_code(&mut br, 704)?);
        }
        let dist_alpha = 16 + ndirect as usize + (48usize << npostfix);
        let mut dist_h = Vec::with_capacity(ntreesd);
        for _ in 0..ntreesd {
            dist_h.push(read_prefix_code(&mut br, dist_alpha)?);
        }
        let postfix_mask = (1u32 << npostfix) - 1;
        let mut remaining: i64 = mlen as i64;
        while remaining > 0 {
            if bi.left == 0 {
                bi.switch(&mut br)?;
            }
            bi.left -= 1;
            let cmd = cmd_h[bi.btype as usize].decode(&mut br)?;
            let group = cmd >> 6;
            const GI: [u32; 11] = [0, 0, 0, 0, 8, 8, 0, 16, 8, 16, 16];
            const GC: [u32; 11] = [0, 8, 0, 8, 0, 8, 16, 0, 16, 8, 16];
            let ic = GI[group as usize] + ((cmd >> 3) & 7);
            let cc = GC[group as usize] + (cmd & 7);
            let insert_len = INS_BASE[ic as usize] + br.read(INS_EXTRA[ic as usize])?;
            let copy_len = COPY_BASE[cc as usize] + br.read(COPY_EXTRA[cc as usize])?;
            for _ in 0..insert_len {
                if bl.left == 0 {
                    bl.switch(&mut br)?;
                }
                bl.left -= 1;
                let n = out.len();
                let p1 = if n >= 1 { out[n - 1] } else { 0 };
                let p2 = if n >= 2 { out[n - 2] } else { 0 };
                let ctx = match cmodes[bl.btype as usize] {
                    0 => p1 & 0x3f,
                    1 => p1 >> 2,
                    2 => LUT0[p1 as usize] | LUT1[p2 as usize],
                    _ => (LUT2[p1 as usize] << 3) | LUT2[p2 as usize],
                };
                let tree = cmap_l[bl.btype as usize * 64 + ctx as usize] as usize;
                let lit = lit_h[tree].decode(&mut br)?;
                out.push(lit as u8);
                remaining -= 1;
                if remaining == 0 {
                    break;
                }
            }
            if remaining <= 0 {
                break;
            }
            // distance
            let dcode: u32;
            let distance: i64;
            if cmd < 128 {
                dcode = 0;
                distance = dist_rb[(dist_rb_idx + 3) & 3];
            } else {
                if bd.left == 0 {
                    bd.switch(&mut br)?;
                }
                bd.left -= 1;
                let dctx = if copy_len > 4 { 3 } else { copy_len - 2 } as usize;
                let tree = cmap_d[bd.btype as usize * 4 + dctx] as usize;
                dcode = dist_h[tree].decode(&mut br)?;
                distance = if dcode < 16 {
                    let last = |k: usize| dist_rb[(dist_rb_idx + 4 - k) & 3];
                    match dcode {
                        0 => last(1),
                        1 => last(2),
                        2 => last(3),
                        3 => last(4),
                        4 => last(1) - 1,
                        5 => last(1) + 1,
                        6 => last(1) - 2,
                        7 => last(1) + 2,
                        8 => last(1) - 3,
                        9 => last(1) + 3,
                        10 => last(2) - 1,
                        11 => last(2) + 1,
                        12 => last(2) - 2,
                        13 => last(2) + 2,
                        14 => last(2) - 3,
                        _ => last(2) + 3,
                    }
                } else if dcode < 16 + ndirect {
                    (dcode - 15) as i64
                } else {
                    let x = dcode - ndirect - 16;
                    let ndistbits = 1 + (x >> (npostfix + 1));
                    let hcode = x >> npostfix;
                    let lcode = x & postfix_mask;
                    let offset = ((2 + (hcode & 1) as i64) << ndistbits) - 4;
                    let extra = br.read(ndistbits)? as i64;
                    ((offset + extra) << npostfix) + lcode as i64 + ndirect as i64 + 1
                };
                if distance <= 0 {
                    return Err(err("invalid distance"));
                }
            }
            let max_distance = out.len().min(max_backward) as i64;
            if distance > max_distance {
                // static dictionary reference
                let l = copy_len as usize;
                if !(4..=24).contains(&l) {
                    return Err(err("invalid dictionary reference"));
                }
                let word_id = (distance - max_distance - 1) as usize;
                let nb = NDBITS[l];
                let idx = word_id & ((1 << nb) - 1);
                let t = word_id >> nb;
                if t >= 121 {
                    return Err(err("invalid transform"));
                }
                let off = DOFFSET[l] as usize + idx * l;
                let before = out.len();
                transform_word(&mut out, &DICT[off..off + l], t);
                remaining -= (out.len() - before) as i64;
                if remaining < 0 {
                    return Err(err("block length mismatch"));
                }
            } else {
                if dcode != 0 {
                    dist_rb[dist_rb_idx & 3] = distance;
                    dist_rb_idx += 1;
                }
                let d = distance as usize;
                let start = out.len() - d;
                for k in 0..copy_len as usize {
                    let b = out[start + k];
                    out.push(b);
                }
                remaining -= copy_len as i64;
                if remaining < 0 {
                    return Err(err("block length mismatch"));
                }
            }
        }
        if islast {
            break;
        }
    }
    Ok(out)
}

