/// Backward bit reader (zstd style).
struct BackBits<'a> {
    data: &'a [u8],
    pos: i64, // number of unread bits remaining (bits [0, pos) unread)
}

impl<'a> BackBits<'a> {
    fn new(data: &'a [u8]) -> Result<Self, CodecError> {
        if data.is_empty() {
            return Err(err("corrupted bitstream"));
        }
        let last = data[data.len() - 1];
        if last == 0 {
            return Err(err("corrupted bitstream"));
        }
        let hb = 7 - last.leading_zeros() as i64;
        Ok(BackBits { data, pos: (data.len() as i64 - 1) * 8 + hb })
    }
    /// Read n bits (MSB-first from the top). Bits beyond the start read as zero
    /// but `pos` goes negative (overflow detection).
    #[inline]
    fn read(&mut self, n: u32) -> u64 {
        if n == 0 {
            return 0;
        }
        self.pos -= n as i64;
        let mut v: u64 = 0;
        for i in (0..n as i64).rev() {
            let b = self.pos + i;
            let bit = if b >= 0 { (self.data[(b >> 3) as usize] >> (b & 7)) & 1 } else { 0 };
            v = (v << 1) | bit as u64;
        }
        v
    }
    #[inline]
    fn peek(&self, n: u32) -> u64 {
        let mut v: u64 = 0;
        for i in (0..n as i64).rev() {
            let b = self.pos - n as i64 + i;
            let bit = if b >= 0 { (self.data[(b >> 3) as usize] >> (b & 7)) & 1 } else { 0 };
            v = (v << 1) | bit as u64;
        }
        v
    }
}

#[derive(Clone)]
struct Fse {
    log: u32,
    sym: Vec<u16>,
    nbits: Vec<u8>,
    base: Vec<u16>,
}

fn build_fse(norm: &[i16], log: u32) -> Fse {
    let size = 1usize << log;
    let mut sym = vec![0u16; size];
    let mut next = vec![0u32; norm.len()];
    let mut high = size - 1;
    for (s, &p) in norm.iter().enumerate() {
        if p == -1 {
            sym[high] = s as u16;
            high = high.wrapping_sub(1);
            next[s] = 1;
        } else {
            next[s] = p.max(0) as u32;
        }
    }
    let step = (size >> 1) + (size >> 3) + 3;
    let mask = size - 1;
    let mut pos = 0usize;
    for (s, &p) in norm.iter().enumerate() {
        for _ in 0..p.max(0) {
            sym[pos] = s as u16;
            pos = (pos + step) & mask;
            while pos > high.min(size - 1) && high < size {
                pos = (pos + step) & mask;
            }
        }
    }
    let mut nbits = vec![0u8; size];
    let mut base = vec![0u16; size];
    for u in 0..size {
        let s = sym[u] as usize;
        let ns = next[s];
        next[s] += 1;
        let hb = 31 - ns.leading_zeros();
        let nb = log - hb;
        nbits[u] = nb as u8;
        base[u] = ((ns << nb) as usize - size) as u16;
    }
    Fse { log, sym, nbits, base }
}

/// Forward LSB-first bit reader for FSE table descriptions.
fn read_fse_table(data: &[u8], max_sym: usize, max_log: u32) -> Result<(Fse, usize), CodecError> {
    let mut bitpos: usize = 0;
    let total_bits = data.len() * 8;
    let rd = |bitpos: usize, n: u32| -> u32 {
        let mut v = 0u32;
        for i in 0..n as usize {
            let b = bitpos + i;
            if b < total_bits && (data[b >> 3] >> (b & 7)) & 1 == 1 {
                v |= 1 << i;
            }
        }
        v
    };
    if total_bits < 4 {
        return Err(err("truncated FSE table"));
    }
    let log = rd(0, 4) + 5;
    bitpos += 4;
    if log > max_log {
        return Err(err("FSE table log too large"));
    }
    let size = 1i32 << log;
    let mut remaining = size + 1;
    let mut threshold = size;
    let mut nb = log + 1;
    let mut norm: Vec<i16> = Vec::new();
    let mut sym = 0usize;
    while remaining > 1 && sym <= max_sym {
        let max = (2 * threshold - 1) - remaining;
        let v = rd(bitpos, nb) as i32;
        let mut count;
        if (v & (threshold - 1)) < max {
            count = v & (threshold - 1);
            bitpos += nb as usize - 1;
        } else {
            count = v & (2 * threshold - 1);
            if count >= threshold {
                count -= max;
            }
            bitpos += nb as usize;
        }
        count -= 1;
        remaining -= count.abs();
        norm.push(count as i16);
        sym += 1;
        if count == 0 {
            loop {
                let r = rd(bitpos, 2) as usize;
                bitpos += 2;
                for _ in 0..r {
                    norm.push(0);
                    sym += 1;
                }
                if r != 3 {
                    break;
                }
            }
        }
        while remaining < threshold {
            nb -= 1;
            threshold >>= 1;
        }
        if bitpos > total_bits {
            return Err(err("truncated FSE table"));
        }
    }
    if remaining != 1 || sym > max_sym + 1 {
        return Err(err("corrupted FSE table"));
    }
    let bytes = bitpos.div_ceil(8);
    Ok((build_fse(&norm, log), bytes))
}

struct Huf {
    max_bits: u32,
    sym: Vec<u8>,
    nbits: Vec<u8>,
}

fn build_huf(weights: &[u8]) -> Result<Huf, CodecError> {
    // weights for symbols 0..n-1 (last implied already appended)
    let mut sum: u32 = 0;
    for &w in weights {
        if w > 0 {
            sum += 1 << (w - 1);
        }
    }
    if sum == 0 {
        return Err(err("corrupted huffman weights"));
    }
    let max_bits = 32 - sum.leading_zeros(); // highbit(sum)+1
    let left = (1u32 << max_bits) - sum;
    if left == 0 || !left.is_power_of_two() {
        return Err(err("corrupted huffman weights"));
    }
    let last_w = left.trailing_zeros() + 1;
    let mut w: Vec<u8> = weights.to_vec();
    w.push(last_w as u8);
    if max_bits > 11 {
        return Err(err("huffman table too large"));
    }
    let size = 1usize << max_bits;
    let mut sym = vec![0u8; size];
    let mut nbits = vec![0u8; size];
    // rank starts
    let mut count = [0u32; 13];
    for &x in &w {
        count[x as usize] += 1;
    }
    let mut start = [0u32; 14];
    let mut acc = 0u32;
    for wt in 1..=max_bits as usize {
        start[wt] = acc;
        acc += count[wt] << (wt - 1);
    }
    for (s, &x) in w.iter().enumerate() {
        if x == 0 {
            continue;
        }
        let len = 1u32 << (x - 1);
        let nb = max_bits + 1 - x as u32;
        let st = start[x as usize];
        for i in st..st + len {
            sym[i as usize] = s as u8;
            nbits[i as usize] = nb as u8;
        }
        start[x as usize] += len;
    }
    Ok(Huf { max_bits, sym, nbits })
}

fn read_huf_tree(data: &[u8]) -> Result<(Huf, usize), CodecError> {
    if data.is_empty() {
        return Err(err("truncated huffman tree"));
    }
    let hb = data[0] as usize;
    let mut weights: Vec<u8> = Vec::new();
    let used;
    if hb >= 128 {
        let n = hb - 127;
        let nbytes = n.div_ceil(2);
        if 1 + nbytes > data.len() {
            return Err(err("truncated huffman tree"));
        }
        for i in 0..n {
            let b = data[1 + i / 2];
            weights.push(if i % 2 == 0 { b >> 4 } else { b & 15 });
        }
        used = 1 + nbytes;
    } else {
        if 1 + hb > data.len() {
            return Err(err("truncated huffman tree"));
        }
        let src = &data[1..1 + hb];
        let (fse, tl) = read_fse_table(src, 255, 6)?;
        let mut bb = BackBits::new(&src[tl..])?;
        let mut s1 = bb.read(fse.log) as usize;
        let mut s2 = bb.read(fse.log) as usize;
        loop {
            weights.push(fse.sym[s1] as u8);
            if weights.len() > 255 {
                return Err(err("corrupted huffman weights"));
            }
            s1 = fse.base[s1] as usize + bb.read(fse.nbits[s1] as u32) as usize;
            if bb.pos < 0 {
                weights.push(fse.sym[s2] as u8);
                break;
            }
            weights.push(fse.sym[s2] as u8);
            s2 = fse.base[s2] as usize + bb.read(fse.nbits[s2] as u32) as usize;
            if bb.pos < 0 {
                weights.push(fse.sym[s1] as u8);
                break;
            }
        }
        used = 1 + hb;
    }
    Ok((build_huf(&weights)?, used))
}

fn huf_decode_stream(h: &Huf, src: &[u8], n: usize, out: &mut Vec<u8>) -> Result<(), CodecError> {
    let mut bb = BackBits::new(src)?;
    for _ in 0..n {
        let v = bb.peek(h.max_bits) as usize;
        out.push(h.sym[v]);
        bb.read(h.nbits[v] as u32);
    }
    if bb.pos != 0 {
        return Err(err("corrupted huffman stream"));
    }
    Ok(())
}

struct FrameState {
    huf: Option<Huf>,
    ll: Option<Fse>,
    of: Option<Fse>,
    ml: Option<Fse>,
    rep: [usize; 3],
}

fn decode_block(
    src: &[u8],
    out: &mut Vec<u8>,
    frame_start: usize,
    st: &mut FrameState,
) -> Result<(), CodecError> {
    // literals section
    if src.is_empty() {
        return Err(err("truncated block"));
    }
    let b0 = src[0];
    let ltype = b0 & 3;
    let sf = (b0 >> 2) & 3;
    let mut p;
    let mut literals: Vec<u8> = Vec::new();
    match ltype {
        0 | 1 => {
            let (rsize, hl) = match sf {
                0 | 2 => ((b0 >> 3) as usize, 1),
                1 => {
                    if src.len() < 2 {
                        return Err(err("truncated literals header"));
                    }
                    (((b0 >> 4) as usize) | ((src[1] as usize) << 4), 2)
                }
                _ => {
                    if src.len() < 3 {
                        return Err(err("truncated literals header"));
                    }
                    (((b0 >> 4) as usize) | ((src[1] as usize) << 4) | ((src[2] as usize) << 12), 3)
                }
            };
            p = hl;
            if ltype == 0 {
                if p + rsize > src.len() {
                    return Err(err("truncated raw literals"));
                }
                literals.extend_from_slice(&src[p..p + rsize]);
                p += rsize;
            } else {
                if p >= src.len() {
                    return Err(err("truncated rle literals"));
                }
                literals.resize(rsize, src[p]);
                p += 1;
            }
        }
        _ => {
            let (rsize, csize, hl, streams) = match sf {
                0 | 1 => {
                    if src.len() < 3 {
                        return Err(err("truncated literals header"));
                    }
                    let v = (b0 as u32 >> 4) | ((src[1] as u32) << 4) | ((src[2] as u32) << 12);
                    ((v & 0x3ff) as usize, (v >> 10) as usize, 3, if sf == 0 { 1 } else { 4 })
                }
                2 => {
                    if src.len() < 4 {
                        return Err(err("truncated literals header"));
                    }
                    let v = (b0 as u32 >> 4) | ((src[1] as u32) << 4) | ((src[2] as u32) << 12) | ((src[3] as u32) << 20);
                    ((v & 0x3fff) as usize, (v >> 14) as usize, 4, 4)
                }
                _ => {
                    if src.len() < 5 {
                        return Err(err("truncated literals header"));
                    }
