pub fn decode(data: &[u8]) -> Result<Vec<u8>, CodecError> {
    if data.is_empty() {
        return Err(err("empty input"));
    }
    let mut out = Vec::new();
    let mut p = 0usize;
    while p < data.len() {
        if p + 4 > data.len() {
            return Err(err("truncated frame"));
        }
        let magic = u32::from_le_bytes([data[p], data[p + 1], data[p + 2], data[p + 3]]);
        if (magic & 0xFFFF_FFF0) == 0x184D_2A50 {
            if p + 8 > data.len() {
                return Err(err("truncated skippable frame"));
            }
            let sz = u32::from_le_bytes([data[p + 4], data[p + 5], data[p + 6], data[p + 7]]) as usize;
            if p + 8 + sz > data.len() {
                return Err(err("truncated skippable frame"));
            }
            p += 8 + sz;
            continue;
        }
        if magic != 0xFD2F_B528 {
            return Err(err("bad magic number"));
        }
        p += 4;
        if p >= data.len() {
            return Err(err("truncated frame header"));
        }
        let fhd = data[p];
        p += 1;
        let fcs_flag = fhd >> 6;
        let single = (fhd >> 5) & 1 == 1;
        let checksum = (fhd >> 2) & 1 == 1;
        let did_flag = fhd & 3;
        if !single {
            if p >= data.len() {
                return Err(err("truncated frame header"));
            }
            p += 1;
        }
        let did_size = [0usize, 1, 2, 4][did_flag as usize];
        p += did_size;
        let fcs_size = match fcs_flag {
            0 => {
                if single {
                    1
                } else {
                    0
                }
            }
            1 => 2,
            2 => 4,
            _ => 8,
        };
        if p + fcs_size > data.len() {
            return Err(err("truncated frame header"));
        }
        p += fcs_size;
        let frame_start = out.len();
        let mut st = FrameState { huf: None, ll: None, of: None, ml: None, rep: [1, 4, 8] };
        loop {
            if p + 3 > data.len() {
                return Err(err("truncated block header"));
            }
            let bh = data[p] as u32 | (data[p + 1] as u32) << 8 | (data[p + 2] as u32) << 16;
            p += 3;
            let last = bh & 1 == 1;
            let btype = (bh >> 1) & 3;
            let bsize = (bh >> 3) as usize;
            match btype {
                0 => {
                    if p + bsize > data.len() {
                        return Err(err("truncated raw block"));
                    }
                    out.extend_from_slice(&data[p..p + bsize]);
                    p += bsize;
                }
                1 => {
                    if p >= data.len() {
                        return Err(err("truncated rle block"));
                    }
                    let b = data[p];
                    out.resize(out.len() + bsize, b);
                    p += 1;
                }
                2 => {
                    if p + bsize > data.len() {
                        return Err(err("truncated compressed block"));
                    }
                    decode_block(&data[p..p + bsize], &mut out, frame_start, &mut st)?;
                    p += bsize;
                }
                _ => return Err(err("reserved block type")),
            }
            if last {
                break;
            }
        }
        if checksum {
            if p + 4 > data.len() {
                return Err(err("truncated content checksum"));
            }
            let want = u32::from_le_bytes([data[p], data[p + 1], data[p + 2], data[p + 3]]);
            let got = xxh64(&out[frame_start..], 0) as u32;
            if want != got {
                return Err(err("content checksum mismatch"));
            }
            p += 4;
        }
    }
    Ok(out)
}

