import heapq, collections, itertools
def heap_variant(hist, leaf_order='asc', internal_first=False, key_height=False, internal_id='counter'):
    syms = sorted(hist)
    if leaf_order == 'desc': syms = syms[::-1]
    if len(syms) == 1: return {syms[0]: 1}
    items = []
    cnt = itertools.count()
    for s in syms:
        o = next(cnt)
        k = (hist[s], 0, o) if not key_height else (hist[s], 0, o)
        items.append([hist[s], 0, o, (s,)])
    # key: (count, [height], order)
    def key(it):
        c, h, o, _ = it
        if key_height: return (c, h, o)
        return (c, o)
    heap = [(key(it), it) for it in items]
    heapq.heapify(heap)
    depth = {s: 0 for s in syms}
    base = 1 << 20
    nxt = 0
    while len(heap) > 1:
        _, a = heapq.heappop(heap)
        _, b = heapq.heappop(heap)
        for s in a[3] + b[3]: depth[s] += 1
        nxt += 1
        if internal_first: o = -nxt
        elif internal_id == 'counter': o = base + nxt
        elif internal_id == 'minsym': o = min(a[2], b[2])
        else: o = base + nxt
        it = [a[0] + b[0], max(a[1], b[1]) + 1, o, a[3] + b[3]]
        heapq.heappush(heap, (key(it), it))
    return depth
def two_queue(hist, leaf_sort='count_sym', tie_prefer_leaf=True):
    syms = list(hist)
    if leaf_sort == 'count_sym': syms.sort(key=lambda s: (hist[s], s))
    elif leaf_sort == 'count_symdesc': syms.sort(key=lambda s: (hist[s], -s))
    if len(syms) == 1: return {syms[0]: 1}
    leaves = collections.deque([(hist[s], (s,)) for s in syms])
    internal = collections.deque()
    depth = {s: 0 for s in syms}
    def pop():
        if not internal: return leaves.popleft()
        if not leaves: return internal.popleft()
        if tie_prefer_leaf:
            return leaves.popleft() if leaves[0][0] <= internal[0][0] else internal.popleft()
        else:
            return leaves.popleft() if leaves[0][0] < internal[0][0] else internal.popleft()
    while len(leaves) + len(internal) > 1:
        a = pop(); b = pop()
        for s in a[1] + b[1]: depth[s] += 1
        internal.append((a[0] + b[0], a[1] + b[1]))
    return depth
