# Python model of the ORIGINAL lumen zstdDecompressSync behaviour (error messages + precedence), as inferred.
import sys
sys.path.insert(0, '/tmp/agent_c')
from zt import (LL_BASE, LL_BITS, ML_BASE, ML_BITS, LL_DEF, ML_DEF, OF_DEF, fse_build, xxh64)

class E(Exception):
    pass

def err(m):
    raise E('zstd: ' + m)

MAXB = 131072

class Rev:
    """backward bit reader; caller checks sentinel/empty beforehand"""
    def __init__(self, data):
        self.val = int.from_bytes(bytes(data), 'little')
        last = data[-1]
        self.pos = (len(data) - 1) * 8 + last.bit_length() - 1
    def read(self, nb):
        if nb == 0:
            return 0
        p = self.pos - nb
        if p >= 0:
            v = (self.val >> p) & ((1 << nb) - 1)
        else:
            v = ((self.val & ((1 << max(self.pos, 0)) - 1)) << (-p)) & ((1 << nb) - 1) if self.pos > 0 else 0
        self.pos = p
        return v
    def peek(self, nb):
        s = self.pos
        v = self.read(nb)
        self.pos = s
        return v

def read_ncount(data, maxsym, maxlog):
    """zero-padded NCount reader. returns (norm, log, consumed_bytes)"""
    val = int.from_bytes(bytes(data), 'little')
    bitpos = 0
    def get(nb):
        return (val >> bitpos) & ((1 << nb) - 1)
    log = get(4) + 5
    bitpos += 4
    if log > maxlog:
        err('FSE accuracy log too large')
    remaining = (1 << log) + 1
    threshold = 1 << log
    nbBits = log + 1
    norm = []
    prev0 = False
    N = maxsym + 1   # alphabet size; the reader tolerates ONE extra symbol index (== N) during parsing
    while remaining > 1:
        if len(norm) > N:
            err('too many symbols in FSE distribution')
        if prev0:
            while True:
                r = get(2)
                bitpos += 2
                norm.extend([0] * r)
                if r != 3:
                    break
            if len(norm) > N:
                err('too many symbols in FSE distribution')
        mx = (2 * threshold - 1) - remaining
        low = get(nbBits - 1)
        if low < mx:
            count = low
            bitpos += nbBits - 1
        else:
            count = get(nbBits)
            if count >= threshold:
                count -= mx
            bitpos += nbBits
        count -= 1
        remaining -= abs(count)
        norm.append(count)
        prev0 = (count == 0)
        while remaining < threshold:
            nbBits -= 1
            threshold >>= 1
    if len(norm) > N:
        err('corrupted FSE distribution')
    return norm, log, (bitpos + 7) // 8

class Model:
    def __init__(self, data):
        self.d = bytes(data)
        self.out = bytearray()

    def run(self):
        d = self.d
        if len(d) == 0:
            err('empty input')
        p = 0
        while p < len(d):
            if len(d) - p < 4:
                err('truncated frame')
            m = int.from_bytes(d[p:p + 4], 'little')
            if (m & 0xFFFFFFF0) == 0x184D2A50:
                if len(d) - p < 8:
                    err('truncated skippable frame')
                sz = int.from_bytes(d[p + 4:p + 8], 'little')
                if sz > len(d) - p - 8:
                    err('truncated skippable frame')
                p += 8 + sz
                continue
            if m != 0xFD2FB528:
                err('bad magic number')
            p = self.frame(p + 4)
        return bytes(self.out)

    def frame(self, p):
        d = self.d
        if p >= len(d):
            err('truncated frame header')
        fhd = d[p]; p += 1
        if fhd & 8:
            err('reserved frame header bit set')
        single = (fhd >> 5) & 1
        if not single:
            if p >= len(d):
                err('truncated frame header')
            p += 1  # window descriptor: ignored
        dsz = [0, 1, 2, 4][fhd & 3]
        if p + dsz > len(d):
            err('truncated frame header')
        did = int.from_bytes(d[p:p + dsz], 'little')
        p += dsz
        if did != 0:
            err('dictionary frames are not supported')
        fsz = [1 if single else 0, 2, 4, 8][fhd >> 6]
        if p + fsz > len(d):
            err('truncated frame header')
        fcs = int.from_bytes(d[p:p + fsz], 'little') if fsz else None
        if fsz == 2:
            fcs += 256
        p += fsz
        start = len(self.out)
        self.huf = None
        self.tabs = {'ll': None, 'of': None, 'ml': None}
        self.rep = [1, 4, 8]
        while True:
            if p + 3 > len(d):
                err('truncated block header')
            bh = int.from_bytes(d[p:p + 3], 'little'); p += 3
            last = bh & 1; bt = (bh >> 1) & 3; bs = bh >> 3
            if bs > MAXB:
                err('block size exceeds maximum')
            if bt == 3:
                err('reserved block type')
            if bt == 0:
                if p + bs > len(d):
                    err('truncated raw block')
                self.out += d[p:p + bs]; p += bs
            elif bt == 1:
                if p + 1 > len(d):
                    err('truncated RLE block')
                self.out += bytes([d[p]]) * bs; p += 1
            else:
                if p + bs > len(d):
                    err('truncated compressed block')
                self.block(d[p:p + bs]); p += bs
            if last:
                break
        if fcs is not None and len(self.out) - start != fcs:
            err('frame content size mismatch')
        if fhd & 4:
            if p + 4 > len(d):
                err('truncated content checksum')
            if (xxh64(bytes(self.out[start:])) & 0xFFFFFFFF) != int.from_bytes(d[p:p + 4], 'little'):
                err('content checksum mismatch')
            p += 4
        return p

    # ---------------- literals
    def block(self, b):
        if len(b) == 0:
            err('missing literals section header')
        lt = b[0] & 3; sf = (b[0] >> 2) & 3
        if lt in (0, 1):
            hs = 1 if sf in (0, 2) else (2 if sf == 1 else 3)
            if len(b) < hs:
                err('truncated literals section')
            if hs == 1:
                regen = b[0] >> 3
            elif hs == 2:
                regen = (b[0] >> 4) | (b[1] << 4)
            else:
                regen = (b[0] >> 4) | (b[1] << 4) | (b[2] << 12)
            if regen > MAXB:
                err('literals section too large')
            if lt == 0:
                if hs + regen > len(b):
                    err('truncated literals section')
                lits = b[hs:hs + regen]; q = hs + regen
            else:
                if hs + 1 > len(b):
                    err('truncated literals section')
                lits = bytes([b[hs]]) * regen; q = hs + 1
        else:
            hs, nb = {0: (3, 10), 1: (3, 10), 2: (4, 14), 3: (5, 18)}[sf]
            if len(b) < hs:
                err('truncated literals section')
            v = int.from_bytes(b[:hs], 'little')
            regen = (v >> 4) & ((1 << nb) - 1)
            csize = (v >> (4 + nb)) & ((1 << nb) - 1)
            if regen > MAXB:
                err('literals section too large')
            if hs + csize > len(b):
                err('truncated literals section')
            c = b[hs:hs + csize]
            q = hs + csize
            if lt == 2:
                tsize = self.tree(c)
            else:
                if self.huf is None:
                    err('treeless literals without a previous Huffman table')
                tsize = 0
            lits = self.huf_lits(c[tsize:], regen, 1 if sf == 0 else 4)
        self.sequences(b[q:], lits)

    def tree(self, c):
        if len(c) == 0:
            err('missing Huffman tree header')
        hb = c[0]
        if hb >= 128:
            n = hb - 127
            nbytes = (n + 1) // 2
            if 1 + nbytes > len(c):
                err('truncated Huffman weights')
            ws = [(c[1 + i // 2] >> 4) if i % 2 == 0 else (c[1 + i // 2] & 15) for i in range(n)]
            tsize = 1 + nbytes
        else:
            if 1 + hb > len(c):
                err('truncated Huffman tree description')
            fc = c[1:1 + hb]
            norm, log, used = read_ncount(fc, 254, 6)
            if used >= len(fc):
                err('truncated Huffman weights bitstream')
            bs = fc[used:]
            if bs[-1] == 0:
                err('bitstream missing sentinel bit')
            table = fse_build(norm, log)
            br = Rev(bs)
            if br.pos < 2 * log:
                err('truncated Huffman weights bitstream')
            s1 = br.read(log); s2 = br.read(log)
            ws = []
            while True:
                sym, nbb, base = table[s1]; ws.append(sym); s1 = base + br.read(nbb)
                if br.pos < 0:
                    ws.append(table[s2][0]); break
                sym, nbb, base = table[s2]; ws.append(sym); s2 = base + br.read(nbb)
                if br.pos < 0:
                    ws.append(table[s1][0]); break
            if len(ws) > 255:
                err('too many Huffman weights')
            tsize = 1 + hb
        if any(w > 11 for w in ws):
            err('Huffman weight too large')
        total = sum((1 << w) >> 1 for w in ws)
        if total == 0:
            err('empty Huffman table')
        tl = total.bit_length()  # highbit+1
        if tl > 11:
            err('Huffman code length too large')
        rest = (1 << tl) - total
        if rest & (rest - 1):
            err('corrupted Huffman weights')
        full = ws + [rest.bit_length()]
        # canonical codes -> decode table
        rank_start = {}
        pos = 0
        for w in range(1, tl + 1):
            rank_start[w] = pos
            pos += sum(1 for x in full if x == w) << (w - 1)
        dt = [None] * (1 << tl)
        for s, w in enumerate(full):
            if w == 0:
                continue
            st = rank_start[w]
            rank_start[w] += 1 << (w - 1)
            for k in range(st, st + (1 << (w - 1))):
                dt[k] = (s, tl + 1 - w)
        self.huf = (dt, tl)
        return tsize

    def huf_stream(self, data, n):
        dt, tl = self.huf
        if len(data) == 0:
            err('empty bitstream')
        if data[-1] == 0:
            err('bitstream missing sentinel bit')
        br = Rev(data)
        o = bytearray()
        for _ in range(n):
            s, L = dt[br.peek(tl)]
            if L > br.pos:
                err('Huffman stream overrun')
            br.read(L)
            o.append(s)
        if br.pos != 0:
            err('Huffman stream not fully consumed')
        return bytes(o)

    def huf_lits(self, c, regen, streams):
        if streams == 1:
            return self.huf_stream(c, regen)
        if len(c) < 6:
            err('truncated literals jump table')
        s1 = int.from_bytes(c[0:2], 'little'); s2 = int.from_bytes(c[2:4], 'little'); s3 = int.from_bytes(c[4:6], 'little')
        if 6 + s1 + s2 + s3 > len(c):
            err('literals jump table exceeds section')
        seg = (regen + 3) // 4
        if 3 * seg > regen:
            err('corrupted 4-stream literals sizes')
        sizes = [s1, s2, s3, len(c) - 6 - s1 - s2 - s3]
        counts = [seg, seg, seg, regen - 3 * seg]
        p = 6
        o = b''
        for k in range(4):
            o += self.huf_stream(c[p:p + sizes[k]], counts[k])
            p += sizes[k]
        return o

    # ---------------- sequences
    def sequences(self, s, lits):
        if len(s) == 0:
            err('missing sequences section header')
        b0 = s[0]
        if b0 < 128:
            n = b0; r = 1
        elif b0 < 255:
            if len(s) < 2:
                err('truncated sequences header')
            n = ((b0 - 128) << 8) + s[1]; r = 2
        else:
            if len(s) < 3:
                err('truncated sequences header')
            n = s[1] + (s[2] << 8) + 0x7F00; r = 3
        if n == 0:
            if r != len(s):
                err('trailing bytes after empty sequences section')
            self.out += lits
            return
        if len(s) < r + 1:
            err('missing sequence compression modes')
        modes = s[r]; r += 1
        if modes & 3:
            err('reserved sequence mode bits set')
        for name, sh, dflt, dlog, maxsym, maxlog in (('ll', 6, LL_DEF, 6, 35, 9), ('of', 4, OF_DEF, 5, 31, 8), ('ml', 2, ML_DEF, 6, 52, 9)):
            m = (modes >> sh) & 3
            if m == 0:
                self.tabs[name] = (fse_build(dflt, dlog), dlog)
            elif m == 1:
                if r >= len(s):
                    err('truncated RLE sequence table')
                sym = s[r]; r += 1
                if sym > maxsym:
                    err('RLE sequence symbol out of range')
                self.tabs[name] = ([(sym, 0, 0)], 0)
            elif m == 2:
                norm, log, used = read_ncount(s[r:], maxsym, maxlog)
                if r + used > len(s):
                    err('truncated FSE table description')
                self.tabs[name] = (fse_build(norm, log), log)
                r += used
            else:
                if self.tabs[name] is None:
                    err('repeat mode without a previous sequence table')
        bs = s[r:]
        if len(bs) == 0:
            err('missing sequences bitstream')
        if bs[-1] == 0:
            err('bitstream missing sentinel bit')
        br = Rev(bs)
        def rd(nb):
            v = br.read(nb)
            if br.pos < 0:
                err('truncated sequences bitstream')
            return v
        (lt, llog), (ot, olog), (mt, mlog) = self.tabs['ll'], self.tabs['of'], self.tabs['ml']
        ls = rd(llog); os_ = rd(olog); ms = rd(mlog)
        lp = 0
        tot = 0
        for i in range(n):
            llc = lt[ls][0]; ofc = ot[os_][0]; mlc = mt[ms][0]
            ov = (1 << ofc) + rd(ofc)
            ml = ML_BASE[mlc] + rd(ML_BITS[mlc])
            ll = LL_BASE[llc] + rd(LL_BITS[llc])
            if ov > 3:
                off = ov - 3
                self.rep = [off, self.rep[0], self.rep[1]]
            else:
                idx = ov - 1 + (1 if ll == 0 else 0)
                if idx == 0:
                    off = self.rep[0]
                elif idx == 3:
                    off = self.rep[0] - 1
                    self.rep = [off, self.rep[0], self.rep[1]]
                else:
                    off = self.rep[idx]
                    if idx == 1:
                        self.rep = [off, self.rep[0], self.rep[2]]
                    else:
                        self.rep = [off, self.rep[0], self.rep[1]]
            if lp + ll > len(lits):
                err('sequence literals overrun')
            if off == 0:
                err('invalid repeat offset')
            self.out += lits[lp:lp + ll]; lp += ll
            if off > len(self.out):
                err('sequence offset too far back')
            if tot + ll + ml > MAXB:
                err('block regenerated size too large')
            tot += ll + ml
            o = self.out
            if off >= ml:
                o += o[len(o) - off:len(o) - off + ml]
            else:
                for k in range(ml):
                    o.append(o[-off])
            if i < n - 1:
                _, nb, base = lt[ls]; ls = base + rd(nb)
                _, nb, base = mt[ms]; ms = base + rd(nb)
                _, nb, base = ot[os_]; os_ = base + rd(nb)
        if br.pos != 0:
            err('sequences bitstream not fully consumed')
        self.out += lits[lp:]

def model(data):
    try:
        return {'ok': True, 'out_hex': Model(data).run().hex()}
    except E as e:
        return {'ok': False, 'message': str(e)}

