                1 => {
                    off = rep[1];
                    *rep = [off, rep[0], rep[2]];
                }
                2 => {
                    off = rep[2];
                    *rep = [off, rep[0], rep[1]];
                }
                _ => {
                    off = rep[0].wrapping_sub(1);
                    *rep = [off, rep[0], rep[1]];
                }
            }
        }
        if lp + ll > lits.len() {
            return Err(err("sequence literals overrun"));
        }
        if off == 0 {
