//! Compression codecs (placeholder docs; final docs written later).

pub mod brotli_dec;
pub mod brotli_enc;
pub mod checksum;
pub mod deflate;
pub mod inflate;
pub mod zstd_dec;
pub mod zstd_enc;

/// Error raised by a decoder.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CodecError {
    pub message: String,
    pub code: &'static str,
    pub errno: i32,
}

impl CodecError {
    pub(crate) fn new(message: impl Into<String>) -> Self {
        CodecError { message: message.into(), code: "", errno: 0 }
    }
}

impl std::fmt::Display for CodecError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.message)
    }
}

impl std::error::Error for CodecError {}

pub use checksum::{adler32, crc32};

/// zlib-family options (node defaults). The original ignores all of them.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeflateOptions {
    pub level: i32,
    pub window_bits: i32,
    pub mem_level: i32,
    pub strategy: i32,
    pub dictionary: Option<Vec<u8>>,
}

